/// Write one (config, variant) result onto a width-`n` sliced block
/// (the block already carries the input row values).
pub fn apply(sh: &KOutShared, kv: &KOut, b: &mut Rt2, n: usize) {
    b.cols[20] = Col::U(AV::Num(sh.c20));
    b.cols[84] = Col::U(AV::Num(sh.c84));
    b.cols[253] = Col::N(sh.c253.to_array()[..n].to_vec());
    b.cols[280] = Col::N(sh.c280.to_array()[..n].to_vec());
    for cell in OUT_UBOOL_CELLS {
        b.cols[*cell as usize] = Col::U(AV::UBool);
    }
}

/// One wide output block per chunk: structure + uniforms cloned
/// once, varying/output columns start empty and grow by appends.
pub fn acc_init(chunk: &Rt2) -> Rt2 {
    let mut acc = Rt2::empty(0, chunk.globals.len(), &[], chunk.cart.clone(), chunk.cache.clone());
    acc.strings = chunk.strings.clone();
    acc.globals = chunk.globals.clone();
    acc.structure = chunk.structure.clone();
    acc.cols = chunk.cols.clone();
    acc.shape_hash = chunk.shape_hash;
    acc.cols[253] = Col::N(Vec::new());
    acc.cols[280] = Col::N(Vec::new());
    acc.cols[234] = Col::N(Vec::new());
    acc.cols[239] = Col::N(Vec::new());
    acc.cols[254] = Col::N(Vec::new());
    acc.cols[268] = Col::N(Vec::new());
    acc.cols[269] = Col::N(Vec::new());
    acc.cols[270] = Col::N(Vec::new());
    acc.cols[271] = Col::N(Vec::new());
    acc.cols[272] = Col::V(Vec::new());
    acc.cols[281] = Col::N(Vec::new());
    for cell in OUT_UBOOL_CELLS {
        acc.cols[*cell as usize] = Col::U(AV::UBool);
    }
    acc
}

/// Append one (config, variant)'s live lanes onto the accumulator.
/// `lo` is the slice base in `chunk` (identity columns read there).
#[allow(unused_variables)]
pub fn append_out(acc: &mut Rt2, chunk: &Rt2, lo: usize, n: usize, live: u16, sh: &KOutShared, kv: &KOut, bd: &mut bool) {
    // fresh: no fork config has written yet, so a uniform slot
    // still holds the chunk's INPUT value (legitimately different).
    let fresh = acc.width == 0;
    for i in 0..n {
        if live & (1 << i) == 0 { continue; }
        if !fresh { if let Col::U(AV::Num(prev)) = &acc.cols[20] { if *prev != sh.c20 { *bd = true; } } }
        acc.cols[20] = Col::U(AV::Num(sh.c20));
        if !fresh { if let Col::U(AV::Num(prev)) = &acc.cols[84] { if *prev != sh.c84 { *bd = true; } } }
        acc.cols[84] = Col::U(AV::Num(sh.c84));
        if let Col::N(v) = &mut acc.cols[253] { v.push(sh.c253.lane(i)); }
        if let Col::N(v) = &mut acc.cols[280] { v.push(sh.c280.lane(i)); }
        let val = match &chunk.cols[234] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[234] { v.push(val); }
        let val = match &chunk.cols[239] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[239] { v.push(val); }
        let val = match &chunk.cols[254] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[254] { v.push(val); }
        let val = match &chunk.cols[268] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[268] { v.push(val); }
        let val = match &chunk.cols[269] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[269] { v.push(val); }
        let val = match &chunk.cols[270] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[270] { v.push(val); }
        let val = match &chunk.cols[271] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[271] { v.push(val); }
        let val = match &chunk.cols[272] { Col::V(s) => s[(lo + i).min(chunk.width - 1)], Col::U(a) => *a, _ => unreachable!() };
        if let Col::V(v) = &mut acc.cols[272] { v.push(val); }
        let val = match &chunk.cols[281] { Col::N(s) => s[(lo + i).min(chunk.width - 1)], Col::U(AV::Num(u)) => *u, _ => unreachable!() };
        if let Col::N(v) = &mut acc.cols[281] { v.push(val); }
        acc.width += 1;
    }
}

