        let c1 = 0x5bf0_3635u64 ^ (234u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        let c2 = 0x27d4_eb2fu64 ^ (234u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
